// package Quarantine;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class HeightAllTheSame {
    public static void main(String[] args)throws IOException {
        BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st=new StringTokenizer(br.readLine());
        int n=Integer.parseInt(st.nextToken());
        int m=Integer.parseInt(st.nextToken());
        int l=Integer.parseInt(st.nextToken());
        int r=Integer.parseInt(st.nextToken());
        long total=1l*n*m;
        int mod=998244353;
        if(total%2!=0){
            long ans=modexp(r-l+1,total,mod);
            System.out.println(ans);
        }
        else{
            int k=r-l+1;
            int e=r/2-l/2;
            if(l%2==0){
                e++;
            }
            int o=k-e;
//            System.out.println(e+" "+o);
            long ans=modexp(e+o,total,mod);
            ans=(ans+modexp(e-o,total,mod))%mod;
            ans=(ans*modexp(2,mod-2,mod))%mod;
            System.out.println(ans);
        }
    }
    public static long modexp(long a,long power,int mod){
        if(power==0){
            return 1;
        }
        if(power==1){
            return a;
        }
        long small=modexp(a,power/2,mod);
        long ans=(small%mod*small%mod)%mod;
        if(power%2!=0){
            ans=(ans%mod*a%mod)%mod;
        }
        return ans;
    }
}

